'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),{PassThrough}=require('node:stream');
const b=require('../../../collectors/nodered/live-integration/private-bootstrap');
function descriptor(){const x={batch_bytes:512,batch_events:1,ca_sha256:'66'.repeat(32),epoch:'18446744073709551615',export_credential:'00000000-0000-4000-8000-000000000001',export_leaf:'11'.repeat(32),generation:'22'.repeat(32),identity:'00'.repeat(32),launch_slot:'88'.repeat(32),launcher_sha256:'99'.repeat(32),manifest_sha256:'33'.repeat(32),marker_public:'44'.repeat(32),nonce:'00000000-0000-4000-8000-000000000002',product_credential:'00000000-0000-4000-8000-000000000003',product_leaf:'55'.repeat(32),profile_id:'00000000-0000-4000-8000-000000000503',queue_bytes:1024,queue_ttl_ms:60000,runtime:'00000000-0000-4000-8000-000000000004',server_leaf:'77'.repeat(32),tenant:'00000000-0000-4000-8000-000000000005',version:1};x.identity=b.commitment(x);return x;}
function frame(value=descriptor()){const bytes=Buffer.from(JSON.stringify(value)),header=Buffer.alloc(8);header.write('CLB1');header.writeUInt32BE(bytes.length,4);return Buffer.concat([header,bytes,Buffer.alloc(32,7)]);}
function run(chunks,{end=true,timeout=80}={}){const stream=new PassThrough(),result=b.readStream(stream,timeout);for(const x of chunks)stream.write(x);if(end)stream.end();return result;}
test('fixed commitment vector and maximum u64 string',()=>{const x=descriptor();assert.equal(x.identity,'d7de41e640d1b3c91b964b60c3c2874f30dc8e86e4b5ab42eeebd0872b2e96a9');assert.deepEqual(b.parse(Buffer.from(JSON.stringify(x))),x);});
test('fragmented frame completes only on EOF',async()=>{const value=frame(),chunks=[...value].map(x=>Buffer.from([x]));const {descriptor:d,seed}=await run(chunks);assert.equal(d.epoch,'18446744073709551615');assert.deepEqual(seed,Buffer.alloc(32,7));});
test('every truncated prefix and missing EOF fails',async()=>{const value=frame();for(let i=0;i<value.length;i++)await assert.rejects(run([value.subarray(0,i)]));await assert.rejects(run([value],{end:false,timeout:10}));});
test('extra, oversized and bad header fail',async()=>{const value=frame();await assert.rejects(run([Buffer.concat([value,Buffer.from([0])])]));const h=Buffer.from('CLB10000');h.writeUInt32BE(16385,4);await assert.rejects(run([h]));const bad=Buffer.from(value);bad[0]=0;await assert.rejects(run([bad]));const alias=Buffer.from(value);Buffer.from([0xc3,0xcc,0xc2,0xb1]).copy(alias);await assert.rejects(run([alias]));});
test('schema requires canonical JSON, matching digest and u64 string',()=>{const x=descriptor();let json=JSON.stringify(x);assert.throws(()=>b.parse(Buffer.from(json.replace('"epoch":','"epoch":"1","epoch":'))));assert.throws(()=>b.parse(Buffer.from(' '+json)));for(const epoch of ['0','01','18446744073709551616',1]){const y={...x,epoch};y.identity=b.commitment(y);assert.throws(()=>b.parse(Buffer.from(JSON.stringify(y))));}assert.throws(()=>b.parse(Buffer.from(JSON.stringify({...x,identity:'ff'.repeat(32)}))));assert.throws(()=>b.parse(Buffer.from(JSON.stringify({...x,extra:1}))));});
test('closed fd selection rejects swapped permit descriptor',async()=>{await assert.rejects(b.read(4,50));});

test('late read error after full frame but before close is fatal',async()=>{const {EventEmitter}=require('node:events');const sock=new EventEmitter();sock.destroy=()=>{};const pending=b.readStream(sock,50);sock.emit('data',frame());sock.emit('end');sock.emit('error',Error('late'));sock.emit('close');await assert.rejects(pending);});
test('bootstrap descriptor cannot be consumed twice',async t=>{const net=require('node:net'),s=new PassThrough();t.mock.method(net,'Socket',function(){return s;});const pending=b.read(3,100);await assert.rejects(b.read(3,100));s.end(frame());const r=await pending;assert.equal(r.seed.length,32);r.seed.fill(0);});
